def get_latest_result(query_id, format=None, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0266000" if __import__("os").path.isdir("./environment_mix/0266000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- helpers
    def _audit(endpoint, status_code, credential_id=None, detail=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + hashlib.sha256(f"{endpoint}|{now}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
            "detail": detail
        })
        _save("request_logs.json", logs)

    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    # ---- validate input
    if not isinstance(query_id, str) or not re.match(r"^dune_qry_[0-9A-HJKMNP-TV-Z]{17,}$", query_id):
        _audit("get_latest_result", "VALIDATION_ERROR", None, "invalid_query_id")
        return _err("VALIDATION_ERROR", "query_id is missing or invalid", field="query_id")
    if format is None:
        format = "csv"
    if not isinstance(format, str) or format != "csv":
        _audit("get_latest_result", "VALIDATION_ERROR", None, "unsupported_format")
        return _err("VALIDATION_ERROR", "Only 'csv' format is supported", field="format")

    # ---- ambient auth: find any active key that can serve reads + not revoked
    keys = _load("api_keys.json")
    if not isinstance(keys, list):
        keys = []
    # require a usable key somewhere in the store (per contract: no auth param must still work if possible)
    usable_key = None
    for k in keys:
        if isinstance(k, dict) and k.get("status") == "active":
            usable_key = k
            break
    if usable_key is None:
        _audit("get_latest_result", "UNAUTHORIZED", None, "no_active_key")
        return _err("UNAUTHORIZED", "No active API key available to authorize this call")

    # ---- locate query
    queries = _load("queries.json")
    if not isinstance(queries, list):
        queries = []
    q = next((r for r in queries if isinstance(r, dict) and r.get("id") == query_id), None)
    if q is None:
        _audit("get_latest_result", "NOT_FOUND", usable_key.get("id"), "query_not_found")
        return _err("NOT_FOUND", "Query not found", query_id=query_id)

    # ---- find newest succeeded result (execution must be succeeded)
    executions = _load("query_executions.json")
    if not isinstance(executions, list):
        executions = []
    results = _load("query_results.json")
    if not isinstance(results, list):
        results = []

    exec_by_id = {e.get("id"): e for e in executions if isinstance(e, dict) and isinstance(e.get("id"), str)}
    candidates = []
    for r in results:
        if not isinstance(r, dict):
            continue
        if r.get("query_id") != query_id:
            continue
        if r.get("format") != "csv":
            continue
        eid = r.get("execution_id")
        e = exec_by_id.get(eid)
        if not e or e.get("status") != "succeeded":
            continue
        gen = _parse_dt(r.get("generated_at"))
        created = _parse_dt(r.get("created_at"))
        sort_dt = gen or created
        if sort_dt is None:
            continue
        candidates.append((sort_dt, r, e))

    if not candidates:
        _audit("get_latest_result", "NOT_FOUND", usable_key.get("id"), "no_successful_result")
        return _err("NOT_FOUND", "No successful execution result found for this query yet", query_id=query_id)

    candidates.sort(key=lambda x: x[0], reverse=True)
    _, r, e = candidates[0]

    body = {
        "query_id": query_id,
        "execution_id": r.get("execution_id"),
        "format": "csv",
        "generated_at": r.get("generated_at"),
        "byte_size": r.get("byte_size"),
        "row_count": r.get("row_count"),
        "checksum_sha256": r.get("checksum_sha256"),
        "csv_text": r.get("csv_text"),
        "meta": {
            "query": {"id": q.get("id"), "dune_query_id": q.get("dune_query_id"), "status": q.get("status")},
            "execution": {"id": e.get("id"), "status": e.get("status"), "finished_at": e.get("finished_at")}
        }
    }

    _audit("get_latest_result", "OK", usable_key.get("id"))
    return body

def run_query(query_id, force_refresh=None, format=None, **_extra):
    import json, os, datetime, re, time, hashlib, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0266000" if __import__("os").path.isdir("./environment_mix/0266000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    # ---- helpers
    def _audit(endpoint, status_code, credential_id=None, detail=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + hashlib.sha256(f"{endpoint}|{now}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
            "detail": detail
        })
        _save("request_logs.json", logs)

    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _b32_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        # 18 chars => satisfies {17,}
        token = "".join(secrets.choice(alphabet) for _ in range(18))
        return f"{prefix}_{token}"

    def _enforce_rate_limit(key_row):
        # Per-key rate limit per minute, based on request_logs.json
        limit = key_row.get("rate_limit_per_minute")
        if not isinstance(limit, int) or limit < 1 or limit > 6000:
            return _err("VALIDATION_ERROR", "API key has invalid rate_limit_per_minute", key_id=key_row.get("id"))
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        window_start = now_dt - datetime.timedelta(seconds=60)
        used = 0
        kid = key_row.get("id")
        for ev in logs:
            if not isinstance(ev, dict):
                continue
            if ev.get("credential_id") != kid:
                continue
            ts = _parse_dt(ev.get("timestamp"))
            if ts is None:
                continue
            if ts >= window_start and ts <= now_dt:
                used += 1
        # reject if this call would exceed limit
        if used >= limit:
            return _err("RATE_LIMIT", "Rate limit exceeded for API key", limit_per_minute=limit)
        return None

    # ---- validate input
    if not isinstance(query_id, str) or not re.match(r"^dune_qry_[0-9A-HJKMNP-TV-Z]{17,}$", query_id):
        _audit("run_query", "VALIDATION_ERROR", None, "invalid_query_id")
        return _err("VALIDATION_ERROR", "query_id is missing or invalid", field="query_id")
    if force_refresh is None:
        force_refresh = False
    if not isinstance(force_refresh, bool):
        _audit("run_query", "VALIDATION_ERROR", None, "invalid_force_refresh")
        return _err("VALIDATION_ERROR", "force_refresh must be a boolean", field="force_refresh")
    if format is None:
        format = "csv"
    if not isinstance(format, str) or format != "csv":
        _audit("run_query", "VALIDATION_ERROR", None, "unsupported_format")
        return _err("VALIDATION_ERROR", "Only 'csv' format is supported", field="format")

    # ---- ambient auth: pick an active key and enforce rate limit
    keys = _load("api_keys.json")
    if not isinstance(keys, list):
        keys = []
    active_keys = [k for k in keys if isinstance(k, dict) and k.get("status") == "active"]
    if not active_keys:
        _audit("run_query", "UNAUTHORIZED", None, "no_active_key")
        return _err("UNAUTHORIZED", "No active API key available to authorize this call")
    # choose a key that isn't rate-limited right now
    calling_key = None
    rate_err = None
    for k in active_keys:
        rate_err = _enforce_rate_limit(k)
        if rate_err is None:
            calling_key = k
            break
    if calling_key is None:
        _audit("run_query", "RATE_LIMIT", active_keys[0].get("id"), "rate_limited")
        return rate_err if rate_err else _err("RATE_LIMIT", "Rate limit exceeded")

    # ---- load core collections
    queries = _load("queries.json")
    if not isinstance(queries, list):
        queries = []
    executions = _load("query_executions.json")
    if not isinstance(executions, list):
        executions = []
    results = _load("query_results.json")
    if not isinstance(results, list):
        results = []

    q = next((r for r in queries if isinstance(r, dict) and r.get("id") == query_id), None)
    if q is None:
        _audit("run_query", "NOT_FOUND", calling_key.get("id"), "query_not_found")
        return _err("NOT_FOUND", "Query not found", query_id=query_id)

    # ---- lifecycle check
    if q.get("status") in ("disabled", "deleted"):
        _audit("run_query", "INVALID_TRANSITION", calling_key.get("id"), f"query_{q.get('status')}_cannot_execute")
        return _err("INVALID_TRANSITION", f"Query in status '{q.get('status')}' cannot be executed", query_id=query_id)

    # ---- caching / TTL: if not forced and TTL > 0, return latest succeeded within ttl
    ttl = q.get("cache_ttl_seconds")
    if not isinstance(ttl, int) or ttl < 0 or ttl > 86400:
        _audit("run_query", "VALIDATION_ERROR", calling_key.get("id"), "invalid_cache_ttl")
        return _err("VALIDATION_ERROR", "Query has invalid cache_ttl_seconds", query_id=query_id)

    def _latest_succeeded_result():
        exec_by_id = {e.get("id"): e for e in executions if isinstance(e, dict) and isinstance(e.get("id"), str)}
        best = None
        best_dt = None
        for r in results:
            if not isinstance(r, dict):
                continue
            if r.get("query_id") != query_id or r.get("format") != "csv":
                continue
            e = exec_by_id.get(r.get("execution_id"))
            if not e or e.get("status") != "succeeded":
                continue
            gen_dt = _parse_dt(r.get("generated_at")) or _parse_dt(r.get("created_at"))
            if gen_dt is None:
                continue
            if best_dt is None or gen_dt > best_dt:
                best_dt = gen_dt
                best = (r, e, gen_dt)
        return best

    if (not force_refresh) and ttl > 0:
        latest = _latest_succeeded_result()
        if latest:
            r, e, gen_dt = latest
            if (now_dt - gen_dt).total_seconds() <= ttl:
                body = {
                    "query_id": query_id,
                    "execution_id": r.get("execution_id"),
                    "format": "csv",
                    "cached": True,
                    "generated_at": r.get("generated_at"),
                    "byte_size": r.get("byte_size"),
                    "row_count": r.get("row_count"),
                    "checksum_sha256": r.get("checksum_sha256"),
                    "csv_text": r.get("csv_text"),
                    "meta": {"cache_ttl_seconds": ttl, "age_seconds": int((now_dt - gen_dt).total_seconds())}
                }
                _audit("run_query", "OK", calling_key.get("id"), "served_from_cache")
                return body

    # ---- create execution queued -> running -> succeeded (simulate completion)
    exec_id = _b32_id("dune_exec")
    execution = {
        "id": exec_id,
        "query_id": query_id,
        "requested_by_key_id": calling_key.get("id"),
        "provider_key_id": q.get("owner_key_id"),
        "status": "queued",
        "upstream_execution_id": None,
        "started_at": None,
        "finished_at": None,
        "error_message": None,
        "duration_ms": None,
        "created_at": now,
        "updated_at": now
    }
    executions.append(execution)

    # transition queued -> running
    started_dt = datetime.datetime.utcnow().replace(microsecond=0)
    started = started_dt.isoformat() + "Z"
    execution["status"] = "running"
    execution["started_at"] = started
    execution["updated_at"] = started

    # transition running -> succeeded, create result
    finished_dt = datetime.datetime.utcnow().replace(microsecond=0)
    finished = finished_dt.isoformat() + "Z"
    execution["status"] = "succeeded"
    execution["finished_at"] = finished
    # simulate small duration
    execution["duration_ms"] = max(0, int((finished_dt - started_dt).total_seconds() * 1000))
    execution["updated_at"] = finished

    # result generation (must satisfy payload constraints)
    csv_text = "col1,col2\n1,2\n"
    byte_size = len(csv_text.encode("utf-8"))
    if byte_size > 52428800:
        _audit("run_query", "VALIDATION_ERROR", calling_key.get("id"), "result_too_large")
        return _err("VALIDATION_ERROR", "Result payload exceeds 50MB limit")
    # ensure "csv_text length corresponds to byte_size"
    if byte_size != len(csv_text.encode("utf-8")):
        _audit("run_query", "VALIDATION_ERROR", calling_key.get("id"), "byte_size_mismatch")
        return _err("VALIDATION_ERROR", "Result payload byte_size mismatch")

    # enforce "query_results may only be inserted for an execution whose status is 'succeeded'"
    if execution["status"] != "succeeded":
        _audit("run_query", "INVALID_TRANSITION", calling_key.get("id"), "execution_not_succeeded_no_result")
        return _err("INVALID_TRANSITION", "Cannot create results for non-succeeded execution", execution_id=exec_id)

    # unique(execution_id): ensure none exists
    for r in results:
        if isinstance(r, dict) and r.get("execution_id") == exec_id:
            _audit("run_query", "CONFLICT", calling_key.get("id"), "duplicate_execution_result")
            return _err("CONFLICT", "A result already exists for this execution", execution_id=exec_id)

    checksum = hashlib.sha256(csv_text.encode("utf-8")).hexdigest()
    res_id = _b32_id("dune_res")
    result_row = {
        "id": res_id,
        "execution_id": exec_id,
        "query_id": query_id,
        "format": "csv",
        "csv_text": csv_text,
        "row_count": 1,
        "byte_size": byte_size,
        "checksum_sha256": checksum,
        "generated_at": finished,
        "created_at": now,
        "updated_at": now
    }
    results.append(result_row)

    # persist
    _save("query_executions.json", executions)
    _save("query_results.json", results)

    body = {
        "query_id": query_id,
        "execution_id": exec_id,
        "format": "csv",
        "cached": False,
        "generated_at": result_row.get("generated_at"),
        "byte_size": result_row.get("byte_size"),
        "row_count": result_row.get("row_count"),
        "checksum_sha256": result_row.get("checksum_sha256"),
        "csv_text": result_row.get("csv_text"),
        "meta": {
            "execution_status": execution.get("status"),
            "duration_ms": execution.get("duration_ms")
        }
    }

    _audit("run_query", "OK", calling_key.get("id"), "executed")
    return body

def list_queries(api_key, status=None, dune_query_id=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, hashlib, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0266000" if __import__("os").path.isdir("./environment_mix/0266000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _audit(endpoint, status_code, credential_id=None, detail=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + hashlib.sha256(f"{endpoint}|{now}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
            "detail": detail
        })
        _save("request_logs.json", logs)

    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _decode_cursor(c):
        if c is None:
            return None
        if not isinstance(c, str) or len(c) < 4:
            return "__invalid__"
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return "__invalid__"
            return obj
        except Exception:
            return "__invalid__"

    def _encode_cursor(obj):
        b = json.dumps(obj, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(b).decode("utf-8").rstrip("=")

    # ---- validate
    if not isinstance(api_key, str) or len(api_key) < 8:
        _audit("list_queries", "VALIDATION_ERROR", None, "invalid_api_key_param")
        return _err("VALIDATION_ERROR", "api_key is missing or invalid", field="api_key")

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "disabled", "deleted"):
            _audit("list_queries", "VALIDATION_ERROR", None, "invalid_status")
            return _err("VALIDATION_ERROR", "Invalid status filter", field="status")

    if dune_query_id is not None:
        if not isinstance(dune_query_id, int) or dune_query_id < 1:
            _audit("list_queries", "VALIDATION_ERROR", None, "invalid_dune_query_id")
            return _err("VALIDATION_ERROR", "Invalid dune_query_id filter", field="dune_query_id")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _audit("list_queries", "VALIDATION_ERROR", None, "invalid_limit")
        return _err("VALIDATION_ERROR", "Invalid limit", field="limit")

    cur_obj = _decode_cursor(cursor)
    if cur_obj == "__invalid__":
        _audit("list_queries", "VALIDATION_ERROR", None, "invalid_cursor")
        return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")

    # ---- authenticate explicit credential: match against id OR last4 OR key_hash (client-visible value could be stored)
    keys = _load("api_keys.json")
    if not isinstance(keys, list):
        keys = []
    key_row = None
    for k in keys:
        if not isinstance(k, dict):
            continue
        if api_key == k.get("id") or api_key == k.get("last4") or api_key == k.get("key_hash") or api_key == k.get("name"):
            key_row = k
            break
    if key_row is None:
        _audit("list_queries", "UNAUTHORIZED", None, "credential_not_found")
        return _err("UNAUTHORIZED", "Invalid API key")
    if key_row.get("status") != "active":
        _audit("list_queries", "UNAUTHORIZED", key_row.get("id"), "key_revoked")
        return _err("UNAUTHORIZED", "API key is revoked")

    # optional scope enforcement (coarse-grained)
    scopes = key_row.get("scopes")
    if isinstance(scopes, list) and scopes:
        # accept any scope that suggests read access
        if not any(isinstance(s, str) and ("read" in s or "query" in s or "*" == s) for s in scopes):
            _audit("list_queries", "UNAUTHORIZED", key_row.get("id"), "missing_scope")
            return _err("UNAUTHORIZED", "API key lacks scope to read queries")

    # ---- rate limit per minute
    rate = key_row.get("rate_limit_per_minute")
    if not isinstance(rate, int) or rate < 1 or rate > 6000:
        _audit("list_queries", "VALIDATION_ERROR", key_row.get("id"), "invalid_rate_limit_config")
        return _err("VALIDATION_ERROR", "API key has invalid rate_limit_per_minute", key_id=key_row.get("id"))
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    window_start = datetime.datetime.utcnow().replace(microsecond=0) - datetime.timedelta(seconds=60)
    used = 0
    for ev in logs:
        if not isinstance(ev, dict):
            continue
        if ev.get("credential_id") != key_row.get("id"):
            continue
        ts = _parse_dt(ev.get("timestamp"))
        if ts and ts >= window_start:
            used += 1
    if used >= rate:
        _audit("list_queries", "RATE_LIMIT", key_row.get("id"), "rate_limited")
        return _err("RATE_LIMIT", "Rate limit exceeded for API key", limit_per_minute=rate)

    # ---- load queries and filter
    queries = _load("queries.json")
    if not isinstance(queries, list):
        queries = []
    rows = [q for q in queries if isinstance(q, dict)]

    if status is not None:
        rows = [q for q in rows if q.get("status") == status]
    if dune_query_id is not None:
        rows = [q for q in rows if q.get("dune_query_id") == dune_query_id]

    # visibility rule: "visible to calling API key" (use owner_key_id when present; otherwise visible)
    visible = []
    for q in rows:
        ok = True
        owner = q.get("owner_key_id")
        if owner is not None:
            ok = (owner == key_row.get("id"))
        if ok:
            visible.append(q)

    # sort by updated_at desc (fallback created_at)
    def _sort_key(q):
        return _parse_dt(q.get("updated_at")) or _parse_dt(q.get("created_at")) or datetime.datetime(1970, 1, 1)

    visible.sort(key=_sort_key, reverse=True)

    # pagination by cursor: cursor carries {"offset": n}
    offset = 0
    if isinstance(cur_obj, dict):
        off = cur_obj.get("offset")
        if isinstance(off, int) and off >= 0:
            offset = off
    page = visible[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < len(visible)
    next_cursor = _encode_cursor({"offset": next_offset}) if has_more else None

    resp = {
        "data": page,
        "meta": {
            "total": len(visible),
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more
        }
    }

    _audit("list_queries", "OK", key_row.get("id"))
    return resp

def get_query(api_key, query_id, **_extra):
