        if lim < 1 or lim > 6000:
            return _err("VALIDATION_ERROR", "rate_limit_per_minute is out of allowed range.", min=1, max=6000)

        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        c = 0
        kid = key_row.get("id")
        for r in logs:
            if not isinstance(r, dict): continue
            if r.get("credential_id") != kid and r.get("key_id") != kid:
                continue
            ts = _parse_dt(r.get("timestamp"))
            if ts is None or ts < cutoff:
                continue
            c += 1
        if c >= lim:
            return _err("RATE_LIMIT", "Rate limit exceeded for this API key.", limit_per_minute=lim)
        return None

    # Validate inputs
    if not isinstance(api_key, str) or len(api_key) < 8:
        _audit("list_query_executions", "VALIDATION_ERROR", None, field="api_key")
        return _err("VALIDATION_ERROR", "api_key is missing or invalid.", field="api_key")

    if not isinstance(query_id, str) or not re.match(r"^dune_qry_[0-9A-HJKMNP-TV-Z]{17,}$", query_id):
        _audit("list_query_executions", "VALIDATION_ERROR", None, field="query_id")
        return _err("VALIDATION_ERROR", "query_id is missing or invalid.", field="query_id")

    if status is not None and status not in ("queued", "running", "succeeded", "failed", "cancelled"):
        _audit("list_query_executions", "VALIDATION_ERROR", None, field="status")
        return _err("VALIDATION_ERROR", "status must be one of: queued, running, succeeded, failed, cancelled.", field="status")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _audit("list_query_executions", "VALIDATION_ERROR", None, field="limit")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", field="limit")

    if cursor is not None and not isinstance(cursor, str):
        _audit("list_query_executions", "VALIDATION_ERROR", None, field="cursor")
        return _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")

    # Authenticate
    key_row, _keys = _auth_key(api_key)
    if not key_row:
        _audit("list_query_executions", "UNAUTHORIZED", None, query_id=query_id)
        return _err("UNAUTHORIZED", "Invalid API key.", query_id=query_id)
    if key_row.get("status") == "revoked":
        _audit("list_query_executions", "UNAUTHORIZED", key_row.get("id"), query_id=query_id)
        return _err("UNAUTHORIZED", "API key is revoked.", query_id=query_id)

    rl_err = _enforce_rate_limit(key_row)
    if rl_err:
        _audit("list_query_executions", rl_err["error"]["code"], key_row.get("id"), query_id=query_id)
        return rl_err

    # Ensure query exists
    queries = _load("queries.json")
    if not isinstance(queries, list): queries = []
    q = None
    for row in queries:
        if isinstance(row, dict) and row.get("id") == query_id:
            q = row
            break
    if not q:
        _audit("list_query_executions", "NOT_FOUND", key_row.get("id"), query_id=query_id)
        return _err("NOT_FOUND", "Query not found.", query_id=query_id)

    # Load executions and filter
    executions = _load("query_executions.json")
    if not isinstance(executions, list): executions = []

    filtered = []
    for e in executions:
        if not isinstance(e, dict): continue
        if e.get("query_id") != query_id:
            continue
        if status is not None and e.get("status") != status:
            continue
        filtered.append(e)

    # Sort newest first by created_at then id
    def _sort_key(e):
        dt = _parse_dt(e.get("created_at")) or datetime.datetime.min
        return (dt, e.get("id") or "")
    filtered.sort(key=_sort_key, reverse=True)

    # Pagination: cursor is the last seen execution id; return rows after it (in sorted order)
    start = 0
    if cursor:
        for i, e in enumerate(filtered):
            if e.get("id") == cursor:
                start = i + 1
                break

    page = filtered[start:start + limit]
    next_cursor = page[-1]["id"] if len(page) == limit else None
    has_more = next_cursor is not None

    _audit("list_query_executions", "OK", key_row.get("id"), query_id=query_id, returned=len(page))
    return {
        "executions": page,
        "pagination": {
            "total": len(filtered),
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

def get_whoami(api_key, **_extra):
    import json, os, datetime, time, hashlib, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0266000" if __import__("os").path.isdir("./environment_mix/0266000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _LOG_FILE = "request_logs.json"
    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _b32_no_pad(nbytes=13):
        return base64.b32encode(os.urandom(nbytes)).decode("ascii").rstrip("=")

    def _new_id_suffix():
        return _b32_no_pad(13)

    def _log(endpoint, key_id, status_txt, started_ts, extra=None):
        logs = _load(_LOG_FILE)
        if not isinstance(logs, list):
            logs = []
        latency_ms = int((time.time() - started_ts) * 1000)
        row = {
            "id": "req_" + _new_id_suffix(),
            "endpoint": endpoint,
            "key_id": key_id,
            "status": status_txt,
            "latency_ms": latency_ms,
            "timestamp": _now_iso()
        }
        if isinstance(extra, dict) and extra:
            row.update(extra)
        logs.append(row)
        _save(_LOG_FILE, logs)

    def _sha256_hex(s):
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _find_key(keys, presented):
        if not isinstance(presented, str):
            return None
        ph = _sha256_hex(presented)
        last4 = presented[-4:] if len(presented) >= 4 else None
        for k in keys:
            if not isinstance(k, dict):
                continue
            if k.get("id") == presented:
                return k
            if k.get("key_hash") == ph:
                return k
        if last4:
            cand = [k for k in keys if isinstance(k, dict) and k.get("last4") == last4]
            if len(cand) == 1:
                return cand[0]
        return None

    def _rate_status(key_row, logs):
        try:
            limit = int(key_row.get("rate_limit_per_minute"))
        except Exception:
            return {"limit_per_minute": None, "remaining_in_window": None, "window_seconds": 60}
        now = datetime.datetime.utcnow()
        window_start = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("key_id") != key_row.get("id"):
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                t = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if t >= window_start:
                cnt += 1
        remaining = max(0, limit - cnt) if isinstance(limit, int) else None
        return {"limit_per_minute": limit, "remaining_in_window": remaining, "window_seconds": 60}

    started = time.time()
    endpoint = "get_whoami"
    key_id_for_log = None

    if not isinstance(api_key, str) or len(api_key) < 8:
        _log(endpoint, key_id_for_log, "error", started, {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "api_key must be a string of at least length 8.")

    keys = _load("api_keys.json")
    if not isinstance(keys, list):
        keys = []
    key = _find_key(keys, api_key)
    key_id_for_log = key.get("id") if isinstance(key, dict) else None

    if not key:
        _log(endpoint, key_id_for_log, "error", started, {"error_code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Invalid API key.")
    if key.get("status") == "revoked":
        _log(endpoint, key_id_for_log, "error", started, {"error_code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "API key is revoked.")

    logs = _load(_LOG_FILE)
    if not isinstance(logs, list):
        logs = []
    rate = _rate_status(key, logs)

    # Do not expose key_hash.
    data = {
        "id": key.get("id"),
        "provider": key.get("provider"),
        "name": key.get("name"),
        "last4": key.get("last4"),
        "status": key.get("status"),
        "scopes": key.get("scopes") if isinstance(key.get("scopes"), list) else [],
        "rate_limit_per_minute": key.get("rate_limit_per_minute"),
        "created_at": key.get("created_at"),
        "updated_at": key.get("updated_at"),
        "revoked_at": key.get("revoked_at"),
        "rate_limit_window": rate
    }

    resp = {"data": data}
    _log(endpoint, key_id_for_log, "ok", started)
    return resp
